import{_ as t,o,c as a,a8 as r}from"./chunks/framework.BppdKxCY.js";const g=JSON.parse('{"title":"EP.59 错误捕获四张网","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.59-error-catching.md","filePath":"comics/EP.59-error-catching.md","lastUpdated":1792817913000}'),s={name:"comics/EP.59-error-catching.md"};function n(c,e,d,l,i,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="ep-59-错误捕获四张网" tabindex="-1">EP.59 错误捕获四张网 <a class="header-anchor" href="#ep-59-错误捕获四张网" aria-label="Permalink to &quot;EP.59 错误捕获四张网&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../46-error-handling">第四十六部分 · 前端错误捕获处理方案</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君的页面线上报错漏了一屏。他明明给代码套了 <code>try/catch</code>，但 <code>setTimeout</code> 回调里的 <code>throw</code> 和 <code>fetch</code> 的 reject 都没被抓到——回调执行时，外层 <code>try</code> 早已出栈，根本不在同一个调用栈。</li><li><strong>第 2 格</strong>：码叔点破关键——前端错误不走同一条通道。同步同栈的错误归 <code>try/catch</code>，JS 运行时与资源 404 归 <code>error</code> 事件（必须捕获阶段），没人接的 Promise 拒绝归 <code>unhandledrejection</code>，框架渲染期错误归 ErrorBoundary / <code>errorHandler</code>。唯一的特例：Promise executor 里的同步 <code>throw</code> 会被自动转成 rejection。</li><li><strong>第 3 格</strong>：像素酱实证多任务编排的坑——<code>Promise.all</code> 一个挂了整体立刻失败，但其余请求还在天上飞，60ms 后慢的那个照样跑完。想真正取消得配 <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/AbortController" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>AbortController</code></a>；要完整账单用 <code>allSettled</code>；多步骤流程失败要逆序补偿。</li><li><strong>第 4 格</strong>：码叔结案——捕获只是上半场，错误还要归一化成 <code>AppError</code>、按 fatal/error/warning/info 分级、同指纹聚合计数，再批量上报。坑点警告：sourcemap 只传监控平台，部署到公网等于源码白送。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-try-catch-为什么罩不住异步" tabindex="-1">第 1 格 · try/catch 为什么罩不住异步 <a class="header-anchor" href="#第-1-格-·-try-catch-为什么罩不住异步" aria-label="Permalink to &quot;第 1 格 · try/catch 为什么罩不住异步&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>try {</span></span>
<span class="line"><span>  setTimeout(() =&gt; { throw e }, 0)   // 回调在另一个宏任务执行</span></span>
<span class="line"><span>  fetch(&#39;/api&#39;)                      // 拒绝走 Promise 通道</span></span>
<span class="line"><span>} catch { /* 永远接不到 */ }</span></span></code></pre></div><p><code>try/catch</code> 的本质是捕获<strong>同一事件循环回合、同一调用栈</strong>里同步抛出的异常。<code>setTimeout</code> 回调执行时外层 <code>try</code> 已经出栈，<code>fetch</code> 的拒绝则压根不是「抛出」而是 Promise 的状态迁移——两者都不在这条通道上。</p><table tabindex="0"><thead><tr><th>写进 try 里的代码</th><th>实际去向</th></tr></thead><tbody><tr><td>同步 <code>throw</code> / <code>JSON.parse</code> 失败</td><td>✅ try/catch 接住</td></tr><tr><td><code>setTimeout</code> / 事件回调里的 throw</td><td>❌ 冒到全局 <code>error</code> 事件</td></tr><tr><td>Promise reject</td><td>❌ 走 <code>.catch</code> / <code>unhandledrejection</code></td></tr></tbody></table><p>可运行实证见 <a href="../examples/46-01-sync-capture.ts">46-01-sync-capture.ts</a>——示例自建了一个微型事件队列，模拟「回调在另一个回合执行」，断言外层 try/catch 永远抓不到。</p><h3 id="第-2-格-·-四类错误四张网" tabindex="-1">第 2 格 · 四类错误四张网 <a class="header-anchor" href="#第-2-格-·-四类错误四张网" aria-label="Permalink to &quot;第 2 格 · 四类错误四张网&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>try/catch           → 同步同栈</span></span>
<span class="line"><span>error (捕获阶段)     → JS 运行时 + 资源 404</span></span>
<span class="line"><span>unhandledrejection  → 没人接的 Promise 拒绝</span></span>
<span class="line"><span>ErrorBoundary       → 框架渲染期/生命周期</span></span></code></pre></div><p>三条硬规则：</p><ol><li><strong>资源错误不冒泡</strong>——<code>&lt;img&gt;</code> / <code>&lt;script&gt;</code> 404 必须在捕获阶段监听（<code>addEventListener(&#39;error&#39;, cb, true)</code>），冒泡阶段一条都收不到；</li><li><strong>Promise executor 是唯一特例</strong>——构造函数同步执行 executor 时自带 try/catch，同步 <code>throw</code> 自动转成 rejection；</li><li><strong>框架边界只管渲染期</strong>——React ErrorBoundary 抓不到事件处理器、异步代码、SSR 与边界自身的错误，这四类仍要靠前两张网。</li></ol><p>全局三件套骨架与「跨域脚本只有 <code>Script error.</code>」的解法（<code>crossorigin=&quot;anonymous&quot;</code> + CDN 配 CORS 头）见正文 <a href="./../46-error-handling#_46-1-错误分类与捕获全景">46.1</a>，冒泡与 rethrow 规则见 <a href="../examples/46-02-async-capture.ts">46-02-async-capture.ts</a>。</p><h3 id="第-3-格-·-all-短路-取消" tabindex="-1">第 3 格 · all 短路 ≠ 取消 <a class="header-anchor" href="#第-3-格-·-all-短路-取消" aria-label="Permalink to &quot;第 3 格 · all 短路 ≠ 取消&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>all([快失败 10ms, 慢成功 50ms])</span></span>
<span class="line"><span>→ 10ms 整体失败（短路）</span></span>
<span class="line"><span>→ 60ms 后:慢成功照样跑完了</span></span></code></pre></div><p><code>Promise.all</code> 的短路只是<strong>整体 Promise 提前落定</strong>，没有任何取消语义——在途请求照样打满服务端。四种编排各管一件事：</p><table tabindex="0"><thead><tr><th>API</th><th>错误语义</th><th>适用</th></tr></thead><tbody><tr><td><code>all</code></td><td>第一个失败即整体失败，其余照跑</td><td>缺一不可的首屏聚合（配 AbortController 取消在途）</td></tr><tr><td><code>allSettled</code></td><td>永不短路，全部落定分开记账</td><td>仪表盘多卡片，部分失败也展示</td></tr><tr><td><code>race</code></td><td>第一个落定无论成败</td><td>超时控制</td></tr><tr><td><code>any</code></td><td>第一个成功，全败抛 AggregateError</td><td>多 CDN 择优容灾</td></tr></tbody></table><p>多步骤流程（下单 → 扣库存 → 支付）失败时要<strong>逆序补偿</strong>：回补库存 → 撤销订单，且补偿动作必须幂等、补偿失败要告警。完整实证见 <a href="../examples/46-03-multi-task-errors.ts">46-03-multi-task-errors.ts</a>，正文展开见 <a href="./../46-error-handling#_46-4-多个异步任务的错误编排-短路、汇总与补偿">46.4</a>。</p><h3 id="第-4-格-·-从捕获到治理" tabindex="-1">第 4 格 · 从捕获到治理 <a class="header-anchor" href="#第-4-格-·-从捕获到治理" aria-label="Permalink to &quot;第 4 格 · 从捕获到治理&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>各通道 → normalizeError → 分级 → 指纹聚合 → 批量上报</span></span>
<span class="line"><span>fatal  → 立即上报 + 阻断</span></span>
<span class="line"><span>error  → 批量队列</span></span>
<span class="line"><span>info   → 只留本地</span></span></code></pre></div><p>管线四步的要点：</p><ul><li><strong>归一化</strong>：所有来源先进 <code>normalizeError()</code> 变成统一的 <code>AppError</code>（name / message / level / fingerprint / cause），下游只认一种结构；</li><li><strong>指纹聚合</strong>：<code>name + message + 堆栈第一帧</code> 做指纹，同一故障聚成一条计数——一次发布事故不该刷出十万条告警；</li><li><strong>批量上报</strong>：队列攒批 + 页面隐藏时 <code>sendBeacon</code> 兜底，别让监控本身成为性能问题；</li><li><strong>sourcemap</strong>：构建产 hidden sourcemap，CI 上传监控平台后从产物删除——公网可下载等于开源整个工程。</li></ul><p>可运行的最小管线见 <a href="../examples/46-04-error-pipeline.ts">46-04-error-pipeline.ts</a>（同一故障连发 5 次聚合成 <code>count=5</code>），正文展开见 <a href="./../46-error-handling#_46-6-工程化落地-归一化、分级与上报管线">46.6</a>，完整监控体系（Web Vitals、行为回溯）见 <a href="./../11-patterns-architecture#_11-2-前端监控与错误上报">11.2</a>。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../46-error-handling#_46-8-本章避坑清单">《46.8 本章避坑清单》</a></p></blockquote><ol><li><strong>用 try/catch 包 setTimeout 回调</strong>：回调在另一个调用栈执行，错误静默漏到全局。回调内部自包，或全局 <code>error</code> 事件兜底。</li><li><strong>资源错误监听忘开捕获阶段</strong>：资源错误不冒泡，冒泡阶段一条都收不到。<code>addEventListener(&#39;error&#39;, cb, true)</code> 第三个参数不能省。</li><li><strong>只挂 error 不挂 unhandledrejection</strong>：Promise 失败完全无感知。两个全局监听必须成对挂在应用入口最前面。</li><li><strong>以为 Promise.all 短路会取消在途请求</strong>：整体失败≠任务停止，失败请求照样打满服务端，还会各触发一次 unhandledrejection。取消要配 AbortController。</li><li><strong>每层都 catch 又 rethrow</strong>：同一错误重复上报刷屏。只在一个层级兜底，中间层透传或带语义 rethrow。</li><li><strong>sourcemap 部署到公网</strong>：源码与内部接口路径白送。hidden sourcemap + CI 上传监控平台后删除产物。</li><li><strong>上报前不脱敏</strong>：token、手机号进日志平台就是合规事故。beforeSend 统一走白名单脱敏。</li></ol><h2 id="自测-3-题" tabindex="-1">自测 3 题 <a class="header-anchor" href="#自测-3-题" aria-label="Permalink to &quot;自测 3 题&quot;">​</a></h2><p><strong>1. 为什么 Promise executor 里的同步 throw 能被 <code>.catch</code> 接到，而 setTimeout 回调里的 throw 不能？</strong></p><details><summary>参考答案</summary><p>Promise 构造函数在<strong>同步执行</strong> executor 时自己包了一层 try/catch，把同步抛出的错误转成该 Promise 的 rejection——所以进得了 Promise 的 <code>.catch</code> 通道。setTimeout 回调则在另一个宏任务里以全新调用栈执行，外层 try 早已出栈，没有任何人替它兜底，只能冒泡到全局 <code>error</code> 事件。一个是「构造器主动转译」，一个是「调用栈彻底断开」。</p></details><p><strong>2. <code>Promise.all</code> 里一个任务失败后，为什么监控平台上可能出现多条 unhandledrejection？怎么避免？</strong></p><details><summary>参考答案</summary><p><code>all</code> 短路后整体 Promise 已落定，但其余任务仍在后台执行。如果这些任务后续也失败且没有自己的 <code>.catch</code>，它们的拒绝就没有任何处理器，会各自触发一次 <code>unhandledrejection</code>。避免方法：给任务数组先统一挂一层就地记账的 <code>.catch</code>（转成占位结果），或用 AbortController 在首个失败时取消在途任务，或改用 <code>allSettled</code>。</p></details><p><strong>3. 错误指纹聚合为什么不能只用 message 做指纹？</strong></p><details><summary>参考答案</summary><p>两个方向都会出问题：message 太粗时（如 <code>Cannot read properties of undefined</code>），几十个不相关的 bug 被聚成一个 issue，无法定位；message 带动态内容时（含用户 id、时间戳），同一故障被拆成几千条，告警刷屏。实用做法是 <code>name + 清洗后的 message + 堆栈第一帧</code>：帧位置区分不同故障，清洗模板抑制动态字段。</p></details>`,35)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
